    <script>
        (function() {
            // ────────────────────────────────────────────
            // HERO COIN — WebGL with ray-intersection shader
            // ────────────────────────────────────────────
            const heroCanvas = document.getElementById('coin-hero');
            const gl = heroCanvas.getContext('webgl', { antialias: true, preserveDrawingBuffer: true });
            if (!gl) {
                heroCanvas.style.background = '#1a1a1f';
                const ctx = heroCanvas.getContext('2d');
